  minStay?: number; // minimum nights (villa only)
  perGuestExtra?: { over: number; fee: number }; // surcharge per guest above `over` (suite only)
  serviceFee?: number; // flat fee added once (villa only)
}

const CATEGORIES: Record<string, CategoryConfig> = {

 standard: { prefix: "standard", nightsMax: 14, guestsMax: 2, base: 80, high: 30 },
  suite: {
    prefix: "suite",
    nightsMax: 21,
    guestsMax: 4,
    base: 150,
    high: 60,
    perGuestExtra: { over: 2, fee: 25 },
  },
  villa: {
    prefix: "villa",
    nightsMax: 28,
    guestsMax: 8,
    base: 300,
    high: 120,
    minStay: 3,
    serviceFee: 500,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
  return { ok: false, error: "bad loyalty" };
}

const config = CATEGORIES[req.category as string];
if (!config) {
  return { ok: false, error: "unknown category" };
}

const nights = req.nights as number;
if (!Number.isInteger(nights) || nights < 1 || nights > config.n

ightsMax) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minStay && nights < config.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > config.gu

estsMax) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const loyal = req.loyaltyYears as number;
  const flex = req.coupon === "VIP" || loyal >= 3

;

  let total = (config.base + (req.season === "high" ? config.high : 0)) * nights;
  if (flex) {
    total -= Math.floor(total / 10);
  }
  if (config.perGuestExtra && guests > config.perGuestExtra.

over) {
    total += config.perGuestExtra.fee;
  }
  if (config.serviceFee) {
    total += config.serviceFee;
  }

  const policy = flex ? "flex" : "strict";
  const line = config.prefix + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

