function orig(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) return { ok: false, error: "malformed request" };
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) return { ok: false, error: "bad loyalty" };
  if (req.category === "standard") {
    if (!Number.isInteger(req.nights) || (req.nights as number) < 1 || (req.nights as number) > 14) return { ok: false, error: "bad nights" };
    if (!Number.isInteger(req.guests) || (req.guests as number) < 1 || (req.guests as number) > 2) return { ok: false, error: "bad guests" };
    if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
    let total = 80 * (req.nights as number);
    if (req.season === "high") total = total + 30 * (req.nights as number);
