    let policy = "strict";
    if (req.coupon === "VIP" || (req.loyaltyYears as number) > 2) policy = "flex";
    const line = "standard:" + String(req.nights) + "n:" + String(total) + ":" + policy;
    return { ok: true, total, policy, line };
  }
  if (req.category === "suite") {
    if (!Number.isInteger(req.nights) || (req.nights as number) < 1 || (req.nights as number) > 21) return { ok: false, error: "bad nights" };
