    if ((req.guests as number) > 2) total = total + 25;
    let policy = "strict";
    if (!((req.loyaltyYears as number) < 3) || req.coupon === "VIP") policy = "flex";
    const line = "suite:" + String(req.nights) + "n:" + String(total) + ":" + policy;
    return { ok: true, total, policy, line };
  }
  if (req.category === "villa") {
    if (!Number.isInteger(req.nights) || (req.nights as number) < 1 || (req.nights as number) > 28) return { ok: false, error: "bad nights" };
    if ((req.nights as number) < 3) return { ok: false, error: "villa minimum stay" };
